pub unsafe extern "C" fn dispatch_dense(value: u8) -> u16 { unsafe { match value { 0 => 7, 1 => 0, 2 => 99, 3 => 2, 4 => 1, 5 => 17, 6 => 31, 7 => 6, _ => u16::MAX } } }

#[unsafe(no_mangle)]
